class Solution { public int[][] substringXorQueries(String s,int[][] queries){Map<Integer,int[]> positions=new HashMap<>();for(int start=0;start<s.length();start++){if(s.charAt(start)=='0'){positions.putIfAbsent(0,new int[]{start,start});continue;}int value=0;for(int end=start;end<s.length()&&end<start+30;end++){value=(value<<1)+(s.charAt(end)-'0');positions.putIfAbsent(value,new int[]{start,end});}}int[][] answer=new int[queries.length][2];for(int i=0;i<queries.length;i++)answer[i]=positions.getOrDefault(queries[i][0]^queries[i][1],new int[]{-1,-1});return answer;} }
